function get_prefs_by_key(store_key, default)
    store_key = checkString(store_key)
    if GameUtils and ECSComponentType then
        ---@type PlayerComponent
        local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComp and checkNumber(playerComp.playerDojo.playerId) > 0 then
            store_key = store_key .. playerComp.playerDojo.playerId
        end
    end
    return checkString(PlayerPrefsUtility.GetEncryptedString(store_key, default or ''))
end

function save_prefs_by_key(store_key, value)
    if not store_key or not value then
        return
    end
    store_key = checkString(store_key)
    if GameUtils and ECSComponentType then
        ---@type PlayerComponent
        local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComp and checkNumber(playerComp.playerDojo.playerId) > 0 then
            store_key = store_key .. playerComp.playerDojo.playerId
        end
    end
    PlayerPrefsUtility.SetEncryptedString(store_key, tostring(value))
    PlayerPrefsUtility.Save()
end

local d = require('Frame.date')
---execute_task_everyday_hour
---每天的几时执行一次方法任务，每天只执行一次
---@param store_key string 记录在prefs中的值的key
---@param hour number 每天的几时更新
---@param task_callback function 需要更新一次任务回处理方法
---@param executed_callback function 已执行过的回调方法
function execute_task_everyday_hour(store_key, hour, task_callback, executed_callback)
    local now = d();
    local dateString = get_prefs_by_key(store_key)
    if string.isEmpty(dateString) then
        --必弹出一次, 当天的5点
        local preDate = d(now:getyear(), now:getmonth(), now:getday(), hour)
        local curDateStr = tostring(preDate)
        save_prefs_by_key(store_key, curDateStr)
        if task_callback then
            task_callback()
        end
    else
        local preDate = d(dateString)
        local t = d.diff(now, preDate)
        if t:spandays() >= 1 then
            local storeDate = d(now:getyear(), now:getmonth(), now:getday(), hour)
            local curDateStr = tostring(storeDate)
            save_prefs_by_key(store_key, curDateStr)
            if task_callback then
                task_callback()
            end

        else
            if executed_callback then
                executed_callback()
            end
        end
    end
end

local function PlayVideo()
    ---此处添加启动画面啥的逻辑
    local IsPlayVideoEnabled = AppEngine.GetConfig("Engine.Dev", "IsPlayVideoEnabled")
    local mainCamera = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("Default"))
    if tonumber(IsPlayVideoEnabled) == 1 then
        local VideoName = AppEngine.GetConfig("Engine.Dev", "VideoName")
        if ResourceModule.IsStreamingAssetsExists(VideoName) then
            if not KTool.IsNull(mainCamera) then
                local go = KTool.CreateEmptyGameObject(mainCamera.gameObject, "Video Player")
                ---@type UnityEngine.Video.VideoPlayer
                local videoPlayer = KTool.GetOrAddComponent(go, typeof(VideoPlayer))
                ---@type UnityEngine.AudioSource
                --local audioSource = KTool.GetOrAddComponent(go, typeof(AudioSource))

                local fullPath = CS.Engine.Lib.PathUtility.Combine(CS.UnityEngine.Application.streamingAssetsPath, VideoName)
                videoPlayer.playOnAwake = false
                --audioSource.playOnAwake = false
                videoPlayer.waitForFirstFrame = true
                videoPlayer.skipOnDrop = true
                videoPlayer.renderMode = CS.UnityEngine.Video.VideoRenderMode.CameraNearPlane
                videoPlayer.targetCamera = mainCamera
                videoPlayer.aspectRatio = CS.UnityEngine.Video.VideoAspectRatio.FitHorizontally
                --videoPlayer.audioOutputMode = CS.UnityEngine.Video .VideoAudioOutputMode.AudioSource
                --videoPlayer.controlledAudioTrackCount = 0
                --audioSource:Pause()
                --videoPlayer:EnableAudioTrack(0, true)
                --videoPlayer:SetTargetAudioSource(0, audioSource)
                videoPlayer.source = CS.UnityEngine.Video.VideoSource.Url
                videoPlayer.url = fullPath
                videoPlayer:Prepare()
                local finishFunction = function(source)
                    if isClick then
                        isClick = false
                        videoPlayer:Pause()
                        -- KTool.SafeDelete(mainCamera.gameObject)
                        Events.Broadcast("OnBeforeStart")
                    end
                end
                videoPlayer:loopPointReached('+', finishFunction)
                videoPlayer:Play()
                --audioSource:Play();
            else
                -- KTool.SafeDelete(mainCamera.gameObject)
                KCookie.Set("START_CHECK_UPDATE", 1)
            end
        else
            KCookie.Set("START_CHECK_UPDATE", 1)
            -- KTool.SafeDelete(mainCamera.gameObject)
        end
    else
        KCookie.Set("START_CHECK_UPDATE", 1)
        Events.Broadcast("OnBeforeStart")
        -- KTool.SafeDelete(mainCamera.gameObject)
    end
end

