function GetApiSalt()
    return "1eeba33bbdff3287f53af9b7bc209b5d"
end

local function UserActivationRequest()
    local isActivated = PlayerPrefsUtility.GetEncryptedInt(UserActivationKey, 0)
    if isActivated == 0 then
        ---发送激活请求
        local WWWEx = CS.Engine.Lib.Updater.WWWEx
        local wwwEx = WWWEx.MakeWWWEx("User/activation", {}, GetApiSalt(), 3, 10)
        cs_coroutine.start(function()
            cs_coroutine.yield_return(wwwEx:LoadAsync(function(www)
                PlayerPrefsUtility.SetEncryptedInt(UserActivationKey, 1)
            end, nil))
        end)
    end
end

local function UserGoogleAdsGclidRequest()
	local HttpModule = CS.Engine.Http.HttpModule
	local gclid = CS.UnityEngine.PlayerPrefs.GetString("gclid","")
	if gclid == "" then
		local shortId = CS.UnityEngine.PlayerPrefs.GetString("shortId","")
		if shortId ~= "" then
			local request = HttpRequest("User/googleAdsGclid")
			local datas = { shortId = shortId }
			request:SetRequestHeader("host", HttpModule.ServerHost)
			request.RequestDatas = datas
			HttpModule.StartRequest(request,
				function(request, response)
					local jsonStr = response.content
					local responseTable = table.deserialize(jsonStr)
					local code = checkInt(responseTable.errCode)
					if code == 0 then
						local data = responseTable.data
						gclid = checkString(data.gclid)
						CS.UnityEngine.PlayerPrefs.SetString("gclid",gclid)
						HttpModule.RequestBodyMeta.IdFa = gclid
					end
					UserActivationRequest()
				end)
		else
			UserActivationRequest()
		end
	else
		 HttpModule.RequestBodyMeta.IdFa = gclid
		 UserActivationRequest()
	end
end


