local function OnBeforeStart()
    if KTool.UNITY_IOS() then
        ---Every time start application of the ios then set the application badge to zero
        CS.Unity.Notifications.iOS.iOSNotificationCenter.ApplicationBadge = 0
    end
    CS.Engine.Lib.Updater.HttpTask.KeepAlive = true ---开启keep alive
	if Application.platform == RuntimePlatform.WindowsPlayer or Application.platform == RuntimePlatform.WindowsEditor then
		UserGoogleAdsGclidRequest()
	else
		UserActivationRequest()
	end
    local canvasTrans = Game.Instance.UIRoot.transform:Find("SplashScreenCanvas")
    if not KTool.IsNull(canvasTrans) then
        local RawImage = canvasTrans.transform:Find("Bg/RawImage")
        if not KTool.IsNull(RawImage) then
            local AppEngine = CS.Engine.Lib.AppEngine
            local version = AppEngine.GetAppBundleVersion()
            local channelId = checkInt(version.ChannelId) 
            if (channelId >= 6007 and channelId <= 6011) or channelId == 6013 then
                KTool.SetActive(RawImage.gameObject, false)
                if channelId ~= 6009 and channelId ~= 6011 then
                    ---@type Engine.UI.RawImageAlterable
                    local RawImageComp =  KTool.GetOrAddComponent(RawImage.gameObject , typeof(CS.Engine.UI.RawImageAlterable))
                    if not KTool.IsNull(RawImageComp) then
                        RawImageComp:LoadSprite("Arts/Textures/SplashScreen/funtoy_logo_duole.png")
                        RawImageComp.OnFinish = function()
                            KTool.SetActive(RawImage.gameObject, true)
                        end
                        RawImageComp.isNativeSize = true
                    end
                end
            else
                KTool.SetActive(RawImage.gameObject, true)
            end
        end
    end    
    StartTrackingIO()
    local instance = Game.Instance
    ---@type Engine.Lib.AppEngine
    local appEngine = instance:GetComponent(typeof(AppEngine))
    appEngine:SetBeforeInitFinish()
    --if KTool.IsMobile() then
    --    CS.Engine.Lib.Logan.LoganCenter.Instance():Send(Config.UPLOAD_URL, { os.date('%Y-%m-%d') })
    --end
    if KTool.UNITY_ANDROID() or KTool.UNITY_EDITOR() then
        ---@type Engine.Lib.BehaviourAction
        local behaviorAction = KTool.GetOrAddComponent(appEngine.gameObject, typeof(BehaviourAction))
        behaviorAction.UpdateAction = function()
            if Input.GetKeyUp(KeyCode.Escape) then
                local AppEngine = CS.Engine.Lib.AppEngine
                local version = AppEngine.GetAppBundleVersion()
                local channelId = checkInt(version.ChannelId) 
                if channelId >= 6007 and channelId <= 6011 then
                    local SDKCenter = CS.Game.Native.MobileSDK.SDKCenter
                    local ProxyPluginName = "PlatformProxy"
                    SDKCenter.InvokePlugin(ProxyPluginName, "exit", "")
                else
                    Events.Broadcast(ANDROID_NATIVE_BACK_ACTION)     
                end            
            end
        end
    end

    CS.Engine.Modules.EventsModule.AddListener("CHANGE_DEVICE_ORIENTATION", function()
        Events.Broadcast("CHANGE_DEVICE_ORIENTATION")
    end)
	
	CS.Engine.Modules.EventsModule.AddListener("GET_TICKET_FOR_WEB_API", function()
        Events.Broadcast(Constants.EventNames.WinSDK,{ type = 95, ticket = CS.FuntoySteamManager.TicketForWebApi,identity = CS.FuntoySteamManager.identity})
    end)
	
	CS.Engine.Modules.EventsModule.AddListener("STEAM_PAY_RESPONSE", function()
        Events.Broadcast(Constants.EventNames.WinSDK,{ type = 90, PayOrderID = CS.FuntoySteamManager.PayOrderID})
    end)


end

